func:
// FETCH SETTINGS of the Provideam fetch: sites, days, dry run.
// In: the daily clock (no payload) or the backfill {start, end} (production
// days YYYY-MM-DD, optional sites). Out: msg.payload = one task
// {site, type, day} per site, report type and day (a split follows).

// Sites to fetch. A site also needs reportSource 'provideam' in 1.1 CONFIG
// and its report bodies in <root>/reference/provideam_reports/site=<Site>/.
var SITES = [
  'Hull',
  'Nottingham',
  'Weinheim'
];
// The clock run fetches this many production days before today, again
// every day, so late corrections in Provideam reach the report.
var DAYS_BACK = 3;
// The first day of the day files. The days before are month files that
// this tab never touches.
var FIRST_DAY = '2026-11-01';
// Longest backfill in days.
var MAX_DAYS = 14;
// true: fetch and convert only, write no file and start no build.
var DRY_RUN = true;
var TYPES = [
  'plan_opt',
  'run_rates',
  'line_losses',
  'volume_loss_correction'
];
var FLOW = 'provideam-fetch';
var IN_BODIES = 'reference/provideam_reports';
var OUT_SOURCE = 'pbi_report/source';

function fail(text) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: text
  });
  node.error(text);
  return null;
}

// Days from the first to the last one, both YYYY-MM-DD.
function dayList(from, to) {
  var out = [];
  var t = Date.parse(from + 'T00:00:00Z');
  var last = Date.parse(to + 'T00:00:00Z');
  while (t <= last) {
    out.push(new Date(t).toISOString().slice(0, 10));
    t += 86400000;
  }
  return out;
}

var shared = glob.get('cfg');
if (!shared) {
  return fail('global cfg is missing: deploy or run the Config tab first');
}
var api = shared.provideam || {};
if (!api.baseUrl || !api.apiKey || /^PUT_/.test(api.apiKey)) {
  return fail('fill in provideam.apiKey in 1.1 CONFIG');
}

var p = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
var backfill = !!(p.start && p.end);
var sites = Array.isArray(p.sites) ? p.sites : SITES;
var notProvideam = sites.filter(function (name) {
  var site = shared.sites.filter(function (s) {
    return s.name === name;
  })[0];
  return !site || site.reportSource !== 'provideam';
});
if (notProvideam.length) {
  return fail('not a Provideam site in 1.1 CONFIG: ' + notProvideam.join(', '));
}

var days;
if (backfill) {
  var isDay = /^\d{4}-\d{2}-\d{2}$/;
  if (!isDay.test(p.start) || !isDay.test(p.end) || p.start > p.end) {
    return fail('start and end must be days YYYY-MM-DD, start not after end');
  }
  if (p.start < FIRST_DAY) {
    return fail('days before ' + FIRST_DAY + ' are month files: not fetched');
  }
  days = dayList(p.start, p.end);
  if (days.length > MAX_DAYS) {
    return fail('a backfill takes ' + MAX_DAYS + ' days at most');
  }
} else {
  var today = Date.parse(new Date().toISOString().slice(0, 10) + 'T00:00:00Z');
  days = dayList(
    new Date(today - DAYS_BACK * 86400000).toISOString().slice(0, 10),
    new Date(today - 86400000).toISOString().slice(0, 10)
  ).filter(function (day) {
    return day >= FIRST_DAY;
  });
}
if (!days.length) {
  node.status({
    fill: 'grey',
    shape: 'ring',
    text: 'no day on or after ' + FIRST_DAY
  });
  return null;
}

var cfg = Object.assign({}, shared);
cfg.dryRun = DRY_RUN;
cfg.bodyFolder = shared.root + '/' + IN_BODIES;
cfg.sourceFolder = shared.root + '/' + OUT_SOURCE;
flow.set('cfg', cfg);

// One task per day, site and type, the days in order.
var tasks = [];
days.forEach(function (day) {
  sites.forEach(function (site) {
    TYPES.forEach(function (type) {
      tasks.push({
        site: site,
        type: type,
        day: day
      });
    });
  });
});
var runId = new Date().toISOString();
flow.set('fetchRun', {
  id: runId,
  sites: sites,
  days: days,
  expected: tasks.length,
  done: 0
});
glob.set('runStatus_' + FLOW, {
  flow: FLOW,
  state: 'running',
  source: backfill ? 'backfill' : 'schedule',
  dryRun: DRY_RUN,
  startedAt: runId,
  lastBeatAt: runId,
  job: {
    sites: sites.join(', '),
    days: days[0] + ' to ' + days[days.length - 1]
  },
  lastLog: ''
});

node.status({
  fill: DRY_RUN ? 'yellow' : 'green',
  shape: 'dot',
  text: tasks.length + ' calls' + (DRY_RUN ? ', DRY RUN' : '')
});
msg.payload = tasks;
return msg;

// Sets the report body file of one task for the read node.
// In: msg.payload = one task {site, type, day} (after the split). Out:
// msg.task and msg.path = <root>/reference/provideam_reports/site=<Site>/
// <type>.json (the body and the settings of the Provideam report).
var cfg = flow.get('cfg');

msg.task = msg.payload;
msg.path = cfg.bodyFolder + '/site=' + msg.task.site + '/';
msg.path += msg.task.type + '.json';
delete msg.payload;
delete msg.parts;
return msg;

// Builds the Provideam report call of one task (read-style POST).
// In: msg.payload = the body file {body, keepTypes}, msg.task. Out: the
// HTTP request for the task's day (msg.method, url, headers, payload).
// Provideam answers HTTP 500 to a body with more than 18 functions.
var PATHS = {
  plan_opt: '/api/v1/Report/ObjectByPeriod',
  run_rates: '/api/v1/Report/ObjectByPeriod',
  line_losses: '/api/v1/report/objectmodelog',
  volume_loss_correction: '/api/v1/report/periodbyobjectandloss'
};
var cfg = flow.get('cfg');

// The read node gives a Buffer, a copied message a {type, data} object.
function text(value) {
  if (value && value.type === 'Buffer' && Array.isArray(value.data)) {
    return Buffer.from(value.data).toString('utf8');
  }
  return String(value);
}

var file = msg.payload;
if (!file || typeof file !== 'object' || Buffer.isBuffer(file) ||
  file.type === 'Buffer') {
  try {
    file = JSON.parse(text(msg.payload));
  } catch (e) {
    node.error('FAILED body file is not JSON: ' + msg.path, msg);
    return null;
  }
}
if (!file.body) {
  node.error('FAILED body file has no body: ' + msg.path, msg);
  return null;
}

var body = file.body;
body.periods = [
  {
    periodParam: {
      pdDay: ['[' + msg.task.day + 'T00:00:00]']
    }
  }
];
msg.task.keepTypes = file.keepTypes || null;
msg.method = 'POST';
msg.url = cfg.provideam.baseUrl + PATHS[msg.task.type];
msg.headers = {
  'apiKey': cfg.provideam.apiKey,
  'Content-Type': 'application/json-patch+json',
  'Accept': 'application/json'
};
msg.payload = JSON.stringify(body);
delete msg.path;
return msg;

// Turns the Provideam answer of one task into the source CSV file, the text
// the SharePoint exports had (docs/provideam-reports.md, October 2026).
// In: the HTTP answer, msg.task. Out 1: the file for the write node (not in
// dry run), out 2: the task result for the join, out 3: a log line.
var HEADS = {
  plan_opt: [
    'SiteName',
    'YYYY-MM-DD',
    'AreaName',
    'MachineName',
    'ShiftName',
    'ShiftStartTime',
    'PartName',
    'Good Parts',
    'Defect Parts',
    'Target',
    'Capacity',
    'OEE',
    'Total Time',
    'Planned OpT',
    'OEE Time',
    'Downtime Units'
  ],
  run_rates: [
    'SiteName',
    'AreaName',
    'MachineName',
    'YYYY-MM-DD HH',
    'PartName',
    'ShiftName',
    'Good Parts',
    'Capacity'
  ],
  line_losses: [
    'SiteName',
    'StartTime',
    'MachineName',
    'PartName',
    'ShiftName',
    'OEELossLvl3Group',
    'OEELossLvl3SubGroup',
    'OEELossLvl3Desc',
    'Duration',
    'ShiftStartDate',
    'Comment'
  ],
  volume_loss_correction: [
    'SiteName',
    'ShiftStartDate',
    'MachineName',
    'OEELossLvl3Group',
    'OEELossLvl3SubGroup',
    'OEELossLvl3Desc',
    'Time',
    'Loss Units'
  ]
};
var cfg = flow.get('cfg');
var task = msg.task;
var site = task.site;

function pad(n) {
  return n < 10 ? '0' + n : String(n);
}
// Seconds as HH:MM:SS. Provideam rounds a half second to even
// (11376.5 s = 03:09:36).
function hms(value) {
  var n = Number(value) || 0;
  var s = Math.round(n);
  if (Math.abs(n % 1) === 0.5 && s % 2) {
    s -= 1;
  }
  return pad(Math.floor(s / 3600)) + ':' + pad(Math.floor(s % 3600 / 60)) +
    ':' + pad(s % 60);
}
function fix2(value) {
  return (Number(value) || 0).toFixed(2);
}
function whole(value) {
  return Math.round(Number(value) || 0);
}
// 0.5125 is 51.3%: round half up after the float noise is cut.
function percent(value) {
  var tenths = Number(((Number(value) || 0) * 1000).toPrecision(12));
  return (Math.round(tenths) / 10).toFixed(1) + '%';
}
function stamp(value) {
  return String(value || '').replace('T', ' ').slice(0, 19);
}
// 10/29/2026 12:00:00 AM -> 2026-10-29
function usDate(value) {
  var m = /^(\d+)\/(\d+)\/(\d{4})/.exec(String(value || ''));
  return m ? m[3] + '-' + pad(Number(m[1])) + '-' + pad(Number(m[2])) : '';
}
// The export has no quotes around a value (the API has them on some part
// names) and no tabs (comments).
function cell(value) {
  var s = value === null || value === undefined ? '' : String(value);
  s = s.replace(/^"(.*)"$/, '$1').replace(/\t/g, ' ');
  if (/[",\n\r]/.test(s)) {
    s = '"' + s.replace(/"/g, '""') + '"';
  }
  return s;
}

function rowOf(x) {
  if (task.type === 'plan_opt') {
    return [
      site,
      x.fdYYYYMMDD,
      x.fdAreaName,
      x.fdMachineName,
      x.fdShiftName,
      stamp(x.fdShiftStartTime),
      x.fdPartName,
      whole(x.fnGoodParts_0),
      whole(x.fnDefectParts_0),
      fix2(x.fnTarget_0),
      fix2(x.fnCapacity_0),
      percent(x.fnOEE_0),
      hms(x.fnTotalTime_0),
      hms(x.fnPlannedOpT_0),
      hms(x.fnOEETime_0),
      fix2(x.fnDowntimeUnits_0)
    ];
  }
  if (task.type === 'run_rates') {
    return [
      site,
      x.fdAreaName,
      x.fdMachineName,
      x.fdYYYYMMDDHH + ':00',
      x.fdPartName,
      x.fdShiftName,
      whole(x.fnGoodParts_0),
      whole(x.fnCapacity_0)
    ];
  }
  if (task.type === 'line_losses') {
    return [
      site,
      stamp(x.fdStartTime),
      x.fdMachineName,
      x.fdPartName || x.fdPartDesc,
      x.fdShiftName,
      x.fdOEELossLvl3Type,
      x.fdOEELossLvl3SubGroup,
      x.fdOEELossLvl3Desc,
      hms(x.fdTime),
      String(x.fdShiftStartDate || '').slice(0, 10),
      x.fdModeComment
    ];
  }
  return [
    site,
    usDate(x.fdShiftStartDate),
    x.fdMachineName,
    x.fdOEELossLvl3Type,
    x.fdOEELossLvl3SubGroup,
    x.fdOEELossLvl3Desc,
    hms(x.fnTime_0),
    fix2(x.fnLossUnits_0)
  ];
}

// Which answer rows are file rows: the export has no Run events, and the
// correction keeps only the loss groups of the site (keepTypes).
function wanted(x) {
  if (x.rowDesc === 'GrandTotal' || !x.fdMachineName) {
    return false;
  }
  if (task.type === 'line_losses') {
    return x.fdOEELossLvl3Type !== 'Run';
  }
  if (task.type === 'volume_loss_correction') {
    return (task.keepTypes || []).indexOf(x.fdOEELossLvl3Type) !== -1;
  }
  return true;
}

var answer = msg.payload;
if (typeof answer === 'string') {
  try {
    answer = JSON.parse(answer);
  } catch (e) {
    answer = null;
  }
}
var key = task.type === 'volume_loss_correction' ?
  'processedLossData' : 'processedData';
var rows = answer && Array.isArray(answer[key]) ? answer[key] : null;
var where = task.day + ' [fetch] ' + site + ' ' + task.type;
var result = {
  site: site,
  type: task.type,
  day: task.day,
  ok: false,
  rows: 0
};
var file = null;
var line;

if (msg.statusCode !== 200 || !rows) {
  line = where + ': FAILED Provideam HTTP ' + msg.statusCode;
  if (msg.statusCode === 200) {
    line += ', no ' + key;
  }
} else {
  var out = [HEADS[task.type].join(',')];
  rows.forEach(function (x) {
    if (wanted(x)) {
      out.push(rowOf(x).map(cell).join(','));
    }
  });
  result.ok = true;
  result.rows = out.length - 1;
  var path = cfg.sourceFolder + '/' + task.type + '/site=' + site + '/';
  path += task.type + '_' + task.day + '.csv';
  line = where + ': ' + result.rows + ' rows';
  if (cfg.dryRun) {
    line += ', dry run (not written)';
  } else {
    line += ' to ' + path;
    file = {
      path: path,
      payload: out.join('\n') + '\n'
    };
  }
}

// The join sends when the last task of the run arrives (msg.complete).
var run = flow.get('fetchRun') || {};
run.done = (run.done || 0) + 1;
flow.set('fetchRun', run);
var joinMsg = {
  payload: result
};
if (run.done >= run.expected) {
  joinMsg.complete = true;
}

node.status({
  fill: result.ok ? 'green' : 'red',
  shape: 'dot',
  text: (run.done || 0) + '/' + (run.expected || '?') + ' ' + site + ' ' +
    task.type
});
return [
  file,
  joinMsg,
  {
    topic: 'log',
    payload: line
  }
];

// Checks the run and builds the job of the two PBI report build tabs.
// In: msg.payload = the task results {site, type, day, ok, rows} (join).
// Out 1: the job {sites, days} (to a wait, then the BACKFILL links of the
// build tabs), not in dry run. Out 2: the summary log line.
var TYPES = 4;
var cfg = flow.get('cfg') || {};
var run = flow.get('fetchRun') || {};
var results = Array.isArray(msg.payload) ? msg.payload : [];

// A day is built when every report type of a site came back.
var okCount = {};
results.forEach(function (r) {
  if (r && r.ok) {
    var key = r.site + '|' + r.day;
    okCount[key] = (okCount[key] || 0) + 1;
  }
});
var days = (run.days || []).filter(function (day) {
  return (run.sites || []).some(function (site) {
    return okCount[site + '|' + day] === TYPES;
  });
});
var failed = results.filter(function (r) {
  return r && !r.ok;
}).length;
var lost = (run.expected || 0) - results.length;

var line = new Date().toISOString().slice(0, 10) + ' [fetch] run: ';
line += results.length + ' of ' + run.expected + ' calls back';
if (failed || lost > 0) {
  line += ', FAILED ' + failed + ' calls, ' + Math.max(lost, 0) + ' lost';
}
line += ', days to build: ' + (days.length ? days.join(', ') : 'none');
if (cfg.dryRun) {
  line += ' (dry run: no build)';
}

var job = null;
if (days.length && !cfg.dryRun) {
  job = {
    topic: 'provideam fetch',
    payload: {
      sites: run.sites,
      days: days
    }
  };
}
node.status({
  fill: failed || lost > 0 ? 'red' : 'green',
  shape: 'dot',
  text: days.length + ' day(s) to build'
});
return [
  job,
  {
    topic: 'log',
    payload: line
  }
];

// Turns an error caught by the catch node into a log line.
// In: the message of a catch node (msg.error).
// Out: a log line for the shared log. Errors of the log nodes themselves
// are dropped (no log loop).
var err = msg.error || {};
var source = (err.source && err.source.name) || 'unknown node';

function textOf(value) {
  if (value === undefined || value === null) {
    return '';
  }
  if (typeof value === 'string') {
    return value;
  }
  return JSON.stringify(value);
}

// Takes the API message out of an error body when there is one.
function apiMessage(value) {
  var body = value;
  if (typeof value === 'string') {
    try {
      body = JSON.parse(value);
    } catch (e) {
      return value;
    }
  }
  var data = body && body.data;
  var list = (data && data.errors) || (body && body.errors);
  if (list && list.length && list[0].message) {
    return list[0].message;
  }
  return textOf(value);
}

if (msg.logBatch) {
  node.status({
    fill: 'red',
    shape: 'ring',
    text: 'log write failed'
  });
  return null;
}

var text = '';
if (msg.day) {
  text += msg.day + ' [' + msg.mode + '] ';
}
text += 'ERROR in ' + source + ': ' + apiMessage(err.message);
return {
  topic: 'log',
  payload: text,
  level: 'error',
  source: source
};

// Turns one log message into a row for the log file.
// In: msg.payload = log text (optional msg.level and msg.source).
// Out: msg.payload = the row, msg.line = the text for the debug node.
var FLOW_NAME = 'provideam-fetch';
var cfg = flow.get('cfg') || {};
var text = String(msg.payload);

var seq = (flow.get('logSeq') || 0) + 1;
flow.set('logSeq', seq);

// Most lines start with the production day and the mode: "2026-09-01 [x] ".
var day = '';
var mode = '';
var message = text;
var parts = /^(\d{4}-\d{2}-\d{2}) \[([^\]]*)\] ([\s\S]*)$/.exec(text);
if (parts) {
  day = parts[1];
  mode = parts[2];
  message = parts[3];
}

var level = msg.level;
if (!level) {
  if (/FAILED/.test(message)) {
    level = 'failed';
  } else if (/NOTHING TO WRITE/.test(message)) {
    level = 'warn';
  } else {
    level = 'info';
  }
}

msg.line = text;
msg.payload = {
  ts_utc: new Date().toISOString(),
  seq: seq,
  flow: FLOW_NAME,
  site: cfg.site || 'all',
  production_day: day,
  mode: mode,
  level: level,
  source: msg.source || 'flow',
  message: message
};
return msg;

// Notes the time of the newest log line of the tab in global context
// lastLog_<flow>. In: every log line (a tap behind the log formatter). Out:
// nothing. A new line clears done_<flow>, so the next quiet period is shown.
var FLOW = 'provideam-fetch';
glob.set('lastLog_' + FLOW, Date.now());
glob.set('done_' + FLOW, false);
var status = glob.get('runStatus_' + FLOW);
if (status) {
  var row = msg.payload || {};
  var line = String(row.message || msg.line || '');
  status.lastBeatAt = new Date().toISOString();
  status.lastLog = line.slice(0, 160);
  if (row.level === 'failed' || row.level === 'error') {
    status.state = 'failed';
  }
  glob.set('runStatus_' + FLOW, status);
}
return null;

// Prepares the write of one batch of log rows (the read node runs next).
// In: msg.payload = array of log rows from the join node.
// Out: msg.path = file of the month, msg.logRows, msg.logBatchId, no payload.
// msg.logBatch keeps errors of the log nodes themselves out of the log.
var FLOW_NAME = 'provideam-fetch';
var cfg = flow.get('cfg') || {};
var root = cfg.root || 'logs_without_root';
var rows = msg.payload;
var month = rows[0].ts_utc.slice(0, 7);

var batchNo = (flow.get('logBatchNo') || 0) + 1;
flow.set('logBatchNo', batchNo);

msg.logRows = rows;
msg.path = root + '/logs/' + FLOW_NAME + '/log_' + month + '.csv';
msg.logBatch = true;
msg.logBatchId = rows[0].ts_utc + '#' + batchNo;
delete msg.payload;
return msg;

// Adds the rows of one batch to the log file of the month.
// In: msg.payload = the old file (read answered) or nothing (no answer).
// Out: msg.payload = the whole new file, the data lake has no append.
// The same batch can arrive twice (read answer, then the wait): once only.
var SEPARATOR = ',';
var KEEP_IDS = 50;
var COLUMNS = [
  'ts_utc',
  'seq',
  'flow',
  'site',
  'production_day',
  'mode',
  'level',
  'source',
  'message'
];

// Quotes inside a field are doubled, line breaks become a space.
function quote(value) {
  var text = (value === undefined || value === null) ? '' : String(value);
  text = text.replace(/"/g, '""').replace(/[\r\n]+/g, ' ');
  return '"' + text + '"';
}

function lineOf(row) {
  return COLUMNS.map(function (name) {
    return quote(row[name]);
  }).join(SEPARATOR);
}

// The read node gives text, or a serialised buffer.
function decode(payload) {
  if (typeof payload === 'string') {
    return payload;
  }
  if (payload && payload.type === 'Buffer' && payload.data) {
    var bin = '';
    payload.data.forEach(function (byte) {
      bin += String.fromCharCode(byte);
    });
    try {
      return decodeURIComponent(escape(bin));
    } catch (e) {
      return bin;
    }
  }
  return null;
}

var rows = msg.logRows.slice();
rows.sort(function (a, b) {
  if (a.ts_utc !== b.ts_utc) {
    return a.ts_utc < b.ts_utc ? -1 : 1;
  }
  return a.seq - b.seq;
});

var done = flow.get('logDone') || [];
var known = flow.get('logKnown') || [];
if (done.indexOf(msg.logBatchId) >= 0) {
  return null;
}

var path = msg.path;
var old = '';
var problem = '';
if (msg.payload === undefined || msg.payload === null) {
  if (known.indexOf(path) >= 0) {
    problem = 'read gave no answer for a file written before';
  }
} else {
  old = decode(msg.payload);
  if (old === null) {
    old = '';
    problem = 'old file is not text';
  }
}
if (problem) {
  // Never replace the old file: write a new one with a time stamp.
  var stamp = new Date().toISOString().replace(/[-:.TZ]/g, '');
  path = path.replace(/\.csv$/, '_' + stamp + '.csv');
  rows.push({
    ts_utc: new Date().toISOString(),
    seq: 0,
    flow: rows[0].flow,
    site: rows[0].site,
    production_day: '',
    mode: '',
    level: 'error',
    source: 'log',
    message: problem + ', wrote ' + path
  });
} else if (known.indexOf(path) < 0) {
  known.push(path);
  flow.set('logKnown', known);
}

var lines = [];
if (!old) {
  lines.push(COLUMNS.map(quote).join(SEPARATOR));
} else if (old.slice(-1) !== '\n') {
  old += '\n';
}
rows.forEach(function (row) {
  lines.push(lineOf(row));
});

done.push(msg.logBatchId);
flow.set('logDone', done.slice(-KEEP_IDS));

msg.payload = old + lines.join('\n') + '\n';
msg.path = path;
delete msg.logRows;
return msg;
